CREATE TABLE IF NOT EXISTS "site_model_monitor_models" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "site_id" INTEGER NOT NULL, "model_name" TEXT NOT NULL, "avg_latency_ms" DOUBLE PRECISION, "success_rate" DOUBLE PRECISION, "avg_tps" DOUBLE PRECISION, "recent_success" TEXT, "window_start" INTEGER, "window_end" INTEGER, "show_throughput" INTEGER, "fetched_at" TEXT NOT NULL, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "site_model_monitor_sites" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "site_id" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "message" TEXT, "models_count" INTEGER NOT NULL DEFAULT 0, "credential_kind" TEXT, "credential_id" INTEGER, "show_throughput" INTEGER, "summary_avg_latency_ms" DOUBLE PRECISION, "summary_success_rate" DOUBLE PRECISION, "summary_avg_tps" DOUBLE PRECISION, "window_start" INTEGER, "window_end" INTEGER, "fetched_at" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "site_model_monitor_models_site_model_unique" ON "site_model_monitor_models" ("site_id", "model_name");
CREATE UNIQUE INDEX "site_model_monitor_sites_site_unique" ON "site_model_monitor_sites" ("site_id");
CREATE INDEX "site_model_monitor_models_model_name_idx" ON "site_model_monitor_models" ("model_name");
CREATE INDEX "site_model_monitor_models_site_id_idx" ON "site_model_monitor_models" ("site_id");
CREATE INDEX "site_model_monitor_sites_status_idx" ON "site_model_monitor_sites" ("status");
